    66|/** Normalize a phone to E.164 (+1...). Accepts "561-644-3503" or "+15616443503". */
    67|export function normalizePhoneToE164(input: string): string {
    68|  const raw = (input || '').trim();
    69|  if (!raw) return '';
    70|  const digits = raw.replace(/\D/g, '');
    71|  if (!digits) return '';
