   157|  const canonicalRequest = ['POST', canonicalUri, '', canonicalHeaders, signedHeaders, bodyHash].join('\n');
   158|  const credentialScope = `${dateStamp}/${region}/${AWS_SERVICE}/aws4_request`;
   159|  const stringToSign = ['AWS4-HMAC-SHA256', amzDate, credentialScope, hash(canonicalRequest)].join('\n');
