   161|  const signature = createHmac('sha256', signingKey).update(stringToSign, 'utf8').digest('hex');
   162|  const authorization = `AWS4-HMAC-SHA256 Credential=${accessKey}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;
   163|
